u a:last-child{border-bottom:0}.sidemenu a:hover{color:#fff;background:#10273a}.badge-count{background:#132e45;color:#9db5c8;border-radius:10px;padding:1px 7px;font-size:10px}.tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.tile{padding:16px;display:flex;align-items:center;gap:12px}.tile-icon{width:40px;height:40px;border-radius:9px;background:#102d47;color:var(--blue);display:flex;align-items:center;justify-content:center;font-size:17px;border:1px solid #1a4160}.tile strong{display:block;font-size:22px}.tile span{font-size:11px;color:var(--muted)}.columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card-body{padding:14px}.btn{display:inline-block;background:var(--blue);color:#fff;border:0;border-radius:5px;padding:8px 11px;font-weight:700;font-size:11px;cursor:pointer}.btn:hover{background:var(--blue2)}.empty{text-align:center;padding:26px 12px;color:#70899d;font-size:12px}.empty .symbol{font-size:26px;color:#34526a;margin-bottom:7px}.service{padding:13px 14px;border-top:1px solid #142a3d;display:grid;grid-template-columns:1fr auto;align-items:center;gap:10px}.service:first-child{border-top:0}.service strong{display:block;font-size:12px}.small{font-size:10px;color:var(--muted);margin-top:3px}.status{font-size:10px;padding:4px 8px;border-radius:12px;background:rgba(66,233,166,.1);color:var(--green)}.status.wait{background:rgba(255,189,89,.1);color:var(--orange)}.invoice,.ticket{padding:12px 14px;border-top:1px solid #142a3d;display:flex;justify-content:space-between;gap:10px}.invoice:first-child,.ticket:first-child{border-top:0}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.action{border:1px solid var(--line);border-radius:5px;padding:11px;color:#a8bbca;background:var(--surface2);font-size:11px}.action:hover{border-color:#315a7b;color:#fff;background:var(--surface3)}.field{width:100%;padding:9px 10px;border:1px solid var(--line);border-radius:5px;background:var(--surface2);color:#e8f2fb;margin-bottom:8px;outline:none}.field:focus{border-color:var(--blue)}.field::placeholder{color:#597286}.footer{margin-top:30px;border-top:1px solid var(--line);background:#081522;color:#526c80;text-align:center;padding:20px;font-size:10px}.mobile-nav{display:none}@media(max-width:900px){.tiles{grid-template-columns:1fr 1fr}.columns{grid-template-columns:1fr}.wrap{grid-template-columns:190px minmax(0,1fr)}}@media(max-width:700px){.topbar{height:58px}.topinner{padding:0 15px}.userlinks .hide{display:none}.mainnav{overflow-x:auto}.navinner{padding:0 8px;min-width:max-content}.mainnav a{padding:11px 13px}.wrap{display:block;padding:0 12px;margin-top:14px}.sidebar{display:none}.hero-inner{padding:18px 15px}.tiles{gap:8px}.tile{padding:12px;gap:8px}.tile-icon{width:34px;height:34px;font-size:15px}.tile strong{font-size:18px}.columns{gap:0}.actions{grid-template-columns:1fr 1fr}.brand{font-size:19px}}@media(max-width:390px){.actions{grid-template-columns:1fr}}
