trong>{{$i->number??('Faktura #'.$i->id)}}</strong><div class="small">Forfalder {{isset($i->due_at)?date('d/m/Y',strtotime($i->due_at)):'—'}}</div></div><div style="text-align:right"><strong>{{number_format((float)($i->total??0),2,',','.')}} {{$i->currency??'DKK'}}</strong><div class="small">{{$i->status}}</div></div></div>@empty<div class="empty">Ingen fakturaer fundet.</div>@endforelse</section></div></div><div class="columns"><section class="card" id="tickets"><div class="card-title">Support tickets</div>@forelse($tickets->take(5) as $t)<a href="/client/tickets/{{$t->id}}" style="color:inherit"><div class="ticket"><div><strong>#{{$t->id}} · {{$t->subject}}</strong><div class="small">{{$t->department??'Support'}}</div></div><span class="status {{$t->status==='closed'?'':'wait'}}">{{$t->status}}</span></div></a>@empty<div class="empty">Du har ingen support tickets.</div>@endforelse</section><section class="card" id="new-ticket"><div class="card-title">Åbn en support ticket</div><form method="POST" action="/client/tickets" class="card-body">@csrf<input class="field" name="subject" required placeholder="Emne"><select class="field" name="department"><option value="support">Support</option><option value="billing">Fakturering</option><option value="sales">Salg</option></select><textarea class="field" name="message" required rows="4" placeholder="Hvordan kan vi hjælpe dig?"></textarea><button class="btn" type="submit">Opret ticket</button></form></section></div></main></div><footer class="footer">© {{date('Y')}} Nodexa · Client Area</footer></body></html>